import{_ as i,o as t,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec_en.md","filePath":"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec_en.md"}'),r={name:"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec_en.md"};function o(s,e,l,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[a("<p><strong>3.10.5 User Management (Account Status and Strike Management)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an authenticated Administrator (ADMIN) selects &quot;Manage Status &amp; Violations&quot; from the user directory (/admin/users).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN manages compliance. Users verify their own email through the activation flow.</li><li><strong>Purpose</strong>: Manage YELLOW/ORANGE/RED strikes and account flags. PENDING_VERIFICATION means unverified email; this function does not recover a lost authenticator.</li><li><strong>Interface</strong>: User Status &amp; Violation Sanction Modal Dialog (SCR-ADM-05), featuring account overview, 3-tier strike counters, habit detection banner, and administrative action forms.</li><li><strong>Data Processing</strong>: Validate ADMIN and target, persist the strike event and audit, consume each eligible yellow batch only once, update clean-period deadline and account publishing restrictions, and create one pending sanction request for RED/three active ORANGE. Pardon references an exact strikeId and does not cascade.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — User Status &amp; Violation Sanction Modal Dialog (SCR-ADM-05):</p><ul><li>Left/Header: Modal title &quot;Manage Status &amp; Violation Sanctions&quot;, security shield icon, and current status badge (ACTIVE green, FLAGGED orange, PENDING_VERIFICATION yellow).</li><li>Center: Profile, status and email verification state; YELLOW x/3 unconverted counter, ORANGE x/3 active counter, RED indicator, converted/expired/pardoned history and clean-period deadline. Actions: add strike, pardon exact strike, unflag after clearing active sanctions. Show pending sanction review link; no Verify 2FA action.</li><li>Buttons: Cancel, Confirm Strike / Pardon / Remove Flag, Open Sanction Review.</li><li>Footer: Audit compliance notice: &quot;All strike additions and pardon actions are permanently recorded in the Audit Log with executing Admin ID and mandatory justification. Hard-deletion of user accounts is strictly prohibited by system architecture.&quot;</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, action (add_strike, remove_strike, unflag), reason; add_strike requires violationLevel (YELLOW/ORANGE/RED) and violationCategory; remove_strike requires strikeId.</li><li><strong>Input optional</strong>: postId, contentVersionId, evidence references.</li><li><strong>System data</strong>: adminId, status, emailVerifiedAt, requirePasswordReset, lastViolationAt, cleanPeriodEndsAt, strike states and conversion links, active counters, pendingSanctionRequestId.</li><li><strong>Output</strong>: User profile update confirmation payload with HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Only ADMIN records/pardons strikes and manages flags, with mandatory reasons and immutable audit.</li><li><strong>BR-92</strong>: Admin cannot hard-delete users; preserve related data and historical strikes. Self-service deletion is a separate flow.</li><li><strong>BR-15</strong>: PENDING_VERIFICATION is unverified email. The user completes email verification; Admin does not bypass it or reset TOTP here. Re-enrolling 2FA is not required by email verification.</li><li><strong>BR-94</strong>: YELLOW is a warning. An active ORANGE strike sets FLAGGED and requires ADMIN approval for publishing; login remains available. RED or three active ORANGE strikes creates a sanction review request under FR 3.10.9; only Admin confirmation deactivates the account.</li><li><strong>BR-95</strong>: Three active, unconverted YELLOW strikes of any violation category produce one independent ORANGE strike. Mark all three source strikes converted and retain their linkage. A fourth YELLOW starts the next batch; six qualifying YELLOW strikes produce two ORANGE strikes. A direct ORANGE can also be recorded. Pardoning a source YELLOW does not pardon the derived ORANGE.</li><li><strong>BR-96</strong>: Each new violation restarts the account clean period of 30 consecutive days without violations. Still-active strikes expire after that clean period, not individually 30 days after creation. Expired or pardoned strikes are not revived; conversion does not count as a second violation. Expiration and pardon preserve immutable history. Removing the last active ORANGE restores publishing eligibility only if no deactivation or activation restriction remains.</li><li><strong>BR-23</strong>: Sole Agency/Workspace Owners may receive profile edits, strikes, flags and confirmed 30-day account deactivation. Other members retain their existing permissions; Owner-only operations wait until restoration. Do not suspend the whole Agency or transfer ownership automatically. Agency ownership is separate from system role.</li><li><strong>BR-15</strong>: Unflag requires offending active strikes to be pardoned/expired first, especially all active ORANGE. It cannot unlock DEACTIVATED accounts; FR 3.10.9 governs the separate 30-day sanction.</li><li><strong>BR-35</strong>: Admin cannot self-sanction or sanction peer ADMIN accounts.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing ADMIN authority or self/peer-admin sanction → MSG39.</li><li>Unknown user or strike → MSG38; missing justification → MSG02.</li><li>Unflag while an active offending strike remains, or target is DEACTIVATED → reject transition.</li><li>Duplicate request/conversion → return existing outcome; do not duplicate strikes or sanctions.</li><li>Valid sole Owner operation is allowed; show Agency impact before deactivation.</li><li>Successful strike/status update → MSG26.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin opens the status/strike modal for a user and reviews active and historical strikes.</li><li>Select add, pardon by strikeId or unflag and enter justification.</li><li>Validate permissions, target state and applicable transition conditions atomically.</li><li>Record the violation; reset the clean period for still-active strikes. Convert eligible yellow batches once, or pardon only the selected strike.</li><li>Recompute FLAGGED and active counters; RED/three ORANGE opens sanction review without deactivation.</li><li>Save audit and refresh UI. A background job expires strikes after 30 clean days; it never bypasses an active account sanction.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Missing justification → MSG02.</li><li>3.a1: Self/peer-admin sanction or missing ADMIN → MSG39.</li><li>3.a2: Pending email verification must use the user activation flow; no administrative verify-2FA bypass.</li><li>3.a3: Stale revision/concurrent pardon or conversion → reload consistent state; retain one audit outcome per action.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Strike lifecycle and source-conversion links are persisted; history is retained.</li><li>FLAGGED users retain login but require ADMIN publishing approval, including scheduled posts.</li><li>RED/three ORANGE leaves a review request awaiting Admin confirmation.</li><li>Email activation and DEACTIVATED sanction clocks remain independent of unflag/strike cleanup.</li></ul>",14)])])}const m=i(r,[["render",o]]);export{g as __pageData,m as default};
